import ghidra.app.script.GhidraScript;
import ghidra.app.cmd.function.CreateFunctionCmd;
import ghidra.program.model.address.*;
import ghidra.program.model.data.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.pcode.JumpTable;
import ghidra.program.model.symbol.*;
import java.io.*;
import java.util.*;
public class N3DRecoverGameSwitches extends GhidraScript {
 public void run() throws Exception {
  try(PrintWriter p=new PrintWriter(getScriptArgs()[0])){
   p.println("owner\tbranch\ttable\tindex\ttarget");
   String[][] specs={{"1010:1118","1010:116d","1010:1172","22"},{"1010:db94","1010:dbcb","1010:dbd0","11"}};
   for(String[] s:specs){
    Address entry=toAddr(s[0]),branch=toAddr(s[1]),table=toAddr(s[2]);int n=Integer.parseInt(s[3]);
    Function f=getFunctionAt(entry);if(f==null)f=createFunction(entry,"RE_switch_candidate_"+s[0].replace(':','_'));
    ArrayList<Address> targets=new ArrayList<>();
    for(int i=0;i<n;i++){
     int off=getShort(table.add(2*i))&0xffff;Address t=toAddr(String.format("1010:%04x",off));
     if(!targets.contains(t))targets.add(t);disassemble(t);
     currentProgram.getListing().getInstructionAt(branch).addOperandReference(0,t,RefType.COMPUTED_JUMP,SourceType.USER_DEFINED);
     p.println(entry+"\t"+branch+"\t"+table+"\t"+i+"\t"+t);
    }
    new JumpTable(branch,targets,true,0).writeOverride(f);
    CreateFunctionCmd.fixupFunctionBody(currentProgram,f,monitor);
    createData(table,new ArrayDataType(WordDataType.dataType,n,2));
    println("RECOVERED_SWITCH "+entry+" entries="+n+" distinct="+targets.size());
   }
  }
 }
}

